<template>
  <section class="h-full w-full overflow-hidden bg-accent absolute top-0 left-0 z-50 touch-none flex flex-col">
    <div id="safe-area-top" />
    <AppLoader v-if="!isCameraLoaded" title="Loading camera..." class="my-auto" />
    <AppError
      v-else-if="error"
      :message="error"
      title="Camera Error"
      suggestion=""
      class="my-auto"
      action-text="Go Back To Petitions List"
    />
    <section
      v-show="isCameraLoaded && !error"
      class="flex flex-col items-center justify-center relative flex-grow px-4"
    >
      <template v-if="Capacitor.isNativePlatform()">
        <div class="p-4 min-h-fit w-full grid grid-cols-12 items-center">
          <div />
          <div class="col-span-10 flex flex-wrap gap-2 items-center justify-self-center text-lg">
            <span>Petition #{{ ballotIndex }}</span>
            <span class="ml-4">Page #{{ displayedPageIndex }}</span>
          </div>
          <NuxtLink
            :to="{
              name: 'verification-ballots-import',
              query: route.query,
              replace: true,
            }"
          >
            <Button variant="outline" size="icon" class="justify-self-end">
              <XIcon class="w-5 h-5 stroke-accent-foreground" />
            </Button>
          </NuxtLink>
        </div>
        <div class="w-full h-full flex items-center">
          <div class="relative w-full h-full overflow-hidden" style="max-height: calc(100vh - 124px)">
            <div v-show="!photoUrl" id="camera-preview" class="h-full w-full" />
            <img v-if="photoUrl" :src="photoUrl" alt="" class="h-full mx-auto object-contain" />
          </div>
        </div>
        <div class="py-2.5 min-h-fit w-full flex justify-center items-center gap-2">
          <Button
            v-if="controlsState === 'initial'"
            variant="outline"
            :loading="isTakingPhoto"
            :prepend-icon="CameraIcon"
            @click="takePhoto"
          >
            Take photo
          </Button>
          <template v-else-if="controlsState === 'photoTaken'">
            <Button variant="outline" :prepend-icon="CameraIcon" @click="retakePhotoClick">Retake</Button>
            <Button variant="outline" :loading="isDoneLoading" :prepend-icon="CheckIcon" @click="doneClick"
              >Done</Button
            >
          </template>
          <template v-else-if="controlsState === 'nextSteps'">
            <Button v-if="isNextPageAvailable" variant="outline" :prepend-icon="FilePlus2Icon" @click="nextPageClick"
              >Next Page
            </Button>
            <Button
              :loading="isAddNewBallotLoading"
              variant="outline"
              :prepend-icon="FilePlusIcon"
              @click="newBallotClick"
              >New Petition
            </Button>
          </template>
        </div>
      </template>
      <template v-else>
        <div id="camera-preview" class="hidden" />
        <AppError
          message="Camera access is only available on a native build."
          title="Camera Unavailable"
          suggestion=""
          class="mt-5"
          action-text="Go Back To Petitions List"
          :to="{ name: 'verification-ballots-import', query: { project_id: projectId, canvasser_id: canvasserId } }"
        />
      </template>
    </section>
    <div id="safe-area-bottom" />
  </section>
</template>

<script setup lang="ts">
import { XIcon, CameraIcon, CheckIcon, FilePlusIcon, FilePlus2Icon } from 'lucide-vue-next';
import { useMobilePermissions } from '~/composables/mobile/useMobilePermissions';
const { requestOne } = useMobilePermissions();
import { CameraPreview, type GridMode } from 'capgo-camera-preview';
import { FetchError } from 'ofetch';
import { useAddPage } from '~/mutations/verification/addPage';
import { useAddBallot } from '~/mutations/verification/addBallot';
import { useBallotDrafts } from '~/queries/verification/ballot';
import { Capacitor } from '@capacitor/core';

definePageMeta({
  hideMobileMenu: true,
});

const isCameraLoaded = ref<boolean>(false);
const error = ref<string | null>(null);

const controlsState = ref<'initial' | 'photoTaken' | 'nextSteps'>('initial');
const photoUrl = ref<string | null>(null);
const capturedFile = ref<File | null>(null);
// Frozen during photoTaken/nextSteps so the header doesn't jump when addNewPage's onSuccess swaps the cached ballot.
const lockedPageIndex = ref<number | null>(null);

onMounted(async () => {
  console.log('onMounted 1');
  await startCamera();
  console.log('onMounted 2');
});

onBeforeUnmount(async () => {
  const route = useRoute('verification-ballots-import-id-camera');
  console.log('onBeforeUnmount 1', route.params.id, JSON.stringify(route.query));
  await stopCamera();
  console.log('onBeforeUnmount 2', route.params.id, JSON.stringify(route.query));
  error.value = null;
});

async function startCamera() {
  if (isCameraLoaded.value) return;
  console.log('startCamera');
  photoUrl.value = null;
  await requestOne('camera');
  try {
    const { isRunning } = await CameraPreview.isRunning();
    if (!isRunning) {
      await CameraPreview.start({
        parent: 'camera-preview',
        position: 'rear',
        toBack: false,
        rotateWhenOrientationChanged: true,
        gridMode: currentPageSidesRatio.value as GridMode,
        aspectRatio: '4:3',
        x: -1,
        y: -1,
        positioning: 'center',
      });
    }
    isCameraLoaded.value = true;
    console.log('Camera started');
  } catch (err: any) {
    console.error(err);
    if (err.name === 'NotAllowedError') {
      error.value = 'Camera access denied. Please allow camera access.';
    } else if (err.name === 'NotFoundError') {
      error.value = 'No camera device found. Please check if your camera works fine.';
    } else {
      error.value = 'Unexpected error while accessing camera.';
    }
    isCameraLoaded.value = true;
    return;
  }
}

async function stopCamera() {
  console.log('Stop camera');
  try {
    const { isRunning } = await CameraPreview.isRunning();
    if (isRunning) {
      await CameraPreview.stop();
    }
  } catch (err) {
    console.warn('Error stopping camera:', err);
  }
  console.log('Camera stopped');
  // photoUrl.value = null;
}

const isTakingPhoto = ref<boolean>(false);

async function takePhoto() {
  isTakingPhoto.value = true;
  // await CameraPreview.setOpacity({ opacity: 0.25 });

  const capturedPicture = await CameraPreview.capture({
    format: 'png',
    photoQualityPrioritization: 'balanced',
  });

  lockedPageIndex.value = pageIndex.value;
  photoUrl.value = 'data:image/png;base64,' + capturedPicture.value;
  controlsState.value = 'photoTaken';
  isTakingPhoto.value = false;
  // await CameraPreview.setOpacity({ opacity: 1.0 });

  capturedFile.value = new File([base64ToBlob(capturedPicture.value, 'image/png')], `photo-${Date.now()}.png`);

  await stopCamera();
}

async function resetState() {
  photoUrl.value = null;
  isCameraLoaded.value = false;
  controlsState.value = 'initial';
  capturedFile.value = null;
  lockedPageIndex.value = null;
  await startCamera();
}

async function retakePhotoClick() {
  await resetState();
}

const { uploadFileData } = useUploadFile();
const isDoneLoading = ref<boolean>(false);

async function doneClick() {
  if (!capturedFile.value) return;
  isDoneLoading.value = true;
  await uploadFileData({ file: capturedFile.value })
    .then(async (data) => {
      await addNewPageFromCameraApp(data.private_url)
        .then(() => {
          controlsState.value = 'nextSteps';
        })
        .catch((error) => {
          console.error('Error adding new page:', error);
          showToastError(error);
        });
    })
    .catch((error) => {
      console.error('Error uploading file:', error);
      showToastError(error);
    })
    .finally(() => {
      isDoneLoading.value = false;
    });
}

async function nextPageClick() {
  if (!ballot.value) return;
  await refetch();
  await resetState();
}

async function newBallotClick() {
  await stopCamera();
  await addNewBallotFromCameraApp();
}

const isNextPageAvailable = computed(() => {
  if (!ballot.value) return false;
  return ballot.value.pages.length < ballot.value.ballot_template.max_pages;
});

function base64ToBlob(base64: string, mimeType: string) {
  // 1. Decode the base64 string into a 'binary' string
  const binaryString = atob(base64);

  // 2. Create an array of byte values
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  // 3. Create a blob from the byte array
  return new Blob([bytes], { type: mimeType });
}

////////////////////////////

const { isLoading, canvasserId, projectId, ballots, canSubmit, error: ballotError, refetch } = useBallotDrafts();

const route = useRoute('verification-ballots-import-id-camera');

const ballot = computed(() => {
  return ballots.value && ballots.value.length > 0 ? ballots.value.find((x) => x.ballot_id === route.params?.id) : null;
});
const ballotIndex = computed(() => {
  return ballot.value ? ballots.value.indexOf(ballot.value) + 1 : null;
});
const pageIndex = computed(() => (ballot.value?.pages?.length || 0) + 1);
const displayedPageIndex = computed(() => lockedPageIndex.value ?? pageIndex.value);
const currenPageTemplate = computed(() => {
  if (!ballot.value) return null;
  return ballot.value.ballot_template.pages && ballot.value.ballot_template.pages.length > 0
    ? ballot.value.ballot_template.pages[ballot.value.ballot_template.pages.length - 1]
    : null;
});
const currentPageSidesRatio = computed(() => {
  return currenPageTemplate.value && currenPageTemplate.value.height && currenPageTemplate.value.width
    ? (currenPageTemplate.value.height / currenPageTemplate.value.width).toFixed(4)
    : (4.0 / 3).toFixed(4);
});

const { addNewBallot, isAddNewBallotLoading } = useAddBallot();
async function addNewBallotFromCameraApp() {
  if (isAddNewBallotLoading.value) return;

  await addNewBallot({
    project_id: projectId.value,
    canvasser_id: canvasserId.value,
  }).catch((err: FetchError) => {
    console.error('Error adding new petition:', err);
  });
  const newBallot = ballots.value && ballots.value.length > 0 ? ballots.value[ballots.value.length - 1] : null;
  if (newBallot) {
    await navigateTo(
      {
        name: 'verification-ballots-import-id-camera',
        params: { id: newBallot.ballot_id },
        query: route.query,
      },
      { replace: true }
    );
  }
}

const { addNewPage } = useAddPage();
async function addNewPageFromCameraApp(s3Url: string) {
  if (!projectId.value || !canvasserId.value || !ballot.value) return;

  await addNewPage({
    projectId: projectId.value,
    canvasserId: canvasserId.value,
    body: {
      ballot_id: ballot.value.ballot_id,
      index: pageIndex.value,
      page_s3_url: s3Url,
    },
  });
}
</script>

<style scoped lang="scss"></style>
