import { addNewBallotPage } from '~/client';
import type { AddPageRequest } from '~/client';

export const useAddPage = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: { body: AddPageRequest; canvasserId: string; projectId: string }) =>
      addNewBallotPage({
        composable: '$fetch',
        body: data.body,
      }),
    onSuccess: async (data, requestData) => {
      const queryCache = useQueryCache();
      queryCache.setQueryData(['ballots.list.draft', requestData.projectId, requestData.canvasserId], () => {
        return data;
      });
      showToastSuccess(`New page added successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    addNewPage: mutateAsync,
    isAddNewPageLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
